"""Analytically defined source and task splits; never generated by the author."""
from copy import deepcopy


def dataset():
    records = []
    for source in ('D1','D2','E1','E2'):
        edges = [[0,1,0,0,0],[1,0,1,0,0]]
        if source in ('D2','E1'):
            edges.append([0,0,0,1,0])
        if source == 'E1':
            edges.append([0,0,0,0,1])
        a = dict(unit='angstrom',lattice=[[1,0,0],[0,1,0],[0,0,1]],
                 frac=[[0,0,0],[.5,0,0]],elements=['C','C'],occupancy=[1,1],edges=edges)
        if source=='D2':
            a['elements']=['C','O']
        if source=='E2':
            a['frac'].append([.25,.25,.25]);a['elements'].append('O');a['occupancy'].append(1)
        for family in ('G','M','S'):
            left,right = deepcopy(a),deepcopy(a)
            if family=='G':
                if source in ('D1','E2'):
                    right['edges'][1][2]=2
                elif source=='D2':
                    right['edges'][-1][2:]=[1,0,0]
                else:
                    right['edges'][-1][2:]=[1,1,0]
            elif family=='M':
                cells = {'D1':[[1,0,0],[.9,.2,0],[0,0,1]],
                         'D2':[[2,0,0],[0,2,0],[0,0,2]],
                         'E1':[[2,0,0],[.5,1,0],[0,0,3]],
                         'E2':[[1,0,0],[.8,.6,0],[0,0,2]]}
                left['lattice']=deepcopy(cells[source]);right['lattice']=deepcopy(cells[source])
                right['frac'][0]={'D1':[.49,.49,0],'D2':[.5,0,0],
                                  'E1':[.25,.5,0],'E2':[.49,.49,0]}[source]
            else:
                n=len(a['frac']);perm=list(reversed(range(n)))
                right['frac']=[[(a['frac'][i][k]+[.25,.125,0][k])%1 for k in range(3)] for i in perm]
                right['elements']=[a['elements'][i] for i in perm]
                right['edges']=[[n-1-i,n-1-j,x,y,z] for i,j,x,y,z in a['edges']]
            block = ('development' if family=='G' else 'task_transfer') if source.startswith('D') else ('source_transfer' if family=='G' else 'joint_transfer')
            records.append(dict(id=source+'-'+family,source=source,family=family,block=block,A=left,B=right))
    return records
